          text: "$1$ 本ずつの記録の合計は $320$ cm、$20$ 本で分けて $320 \\div 20 = 16$ cm。いっぽう [階級値] は $10,\\ 14,\\ 18,\\ 22$ cm で、$10 \\times 3 + 14 \\times 6 + 18 \\times 8 + 22 \\times 3 = 324$ cm、$324 \\div 20 = 16.2$ cm。差は $16.2 - 16 = 0.2$ cm。**表から出た平均は、真の平均ではありません。** 原因は階級の中身にあって、たとえば「$12$ 以上 $16$ 未満」の $6$ 本は $12,\\ 13,\\ 13,\\ 14,\\ 15,\\ 15$ で合計 $82$ cm なのに、代表 $14$ で数えると $84$ cm——階級の中で下寄りに集まっている分だけ、代表が多めに見積もってしまう。しかも度数分布表しか無い状況では、このずれが**どちら向きにどれだけあるかを知ることさえできない**（比べる相手の材料が無いのだから）。それでも近似を使うのは、近似だと知って使うかぎり役に立つからです。中心の問いへの部分回答：「（ほぼ）正しく戻ってくる」の**ほぼ**の正体がこれ——基準をずらす工夫は答えを $1$ ミリも変えないのに、代表で代用する工夫は答えを変える。$2$ つは似て見えて、質がまるで違う。",
